}

/* Hangul is first-class: Black Han Sans, a chunky Y2K Korean display face.
   In body settings it carries every Korean glyph; the Latin body font is
   Syne, which has Korean coverage of zero, so Hangul falls straight through. */
.chrome-root :lang(ko) {
