  color: var(--chrome-ink);
  text-shadow: none;
}

/* Keyboard focus: an accent halo ring, art-directed for chrome */
.chrome-root :focus-visible {
  outline: 2px solid var(--chrome-accent);
  outline-offset: 3px;
  border-radius: 2px;
}

