/* ==========================================================================
   Hero — the chrome shader headline + holographic foil frame
   ========================================================================== */

.chrome-hero {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  min-height: 100vh;
  min-height: 100svh;
  padding: clamp(40px, 8vh, 96px) clamp(28px, 6vw, 80px) clamp(16px, 3vh, 40px);
  text-align: center;
}

/* The generated liquid-chrome render — the ambient metal of the stage,
   behind the holographic scrim. Blurred and partly veiled so it reads as
   atmosphere (a chrome studio), not a literal photo. */
.chrome-hero__metal-bg {
  position: absolute;
  inset: -5%;
  width: 110%;
  height: 110%;
  object-fit: cover;
  object-position: center 70%;
  opacity: 0.18;
  filter: blur(6px) saturate(1.1) brightness(0.6);
  z-index: 0;
  pointer-events: none;
}

/* The scrim: a flat holographic gradient behind everything, so no-JS and
   shader-failure never show a hole. It is the page's permanent backlight. */
.chrome-hero__scrim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 90% at 50% 22%, var(--chrome-holo-pink) 0%, transparent 55%),
    linear-gradient(115deg, var(--chrome-holo-sky) 0%, var(--chrome-holo-mist) 38%, var(--chrome-holo-mint) 100%);
  z-index: 0;
  opacity: 0.82;
}

/* Lift all flow children above the background layers, but keep the
   absolute background layers (metal-bg, scrim) out of the flow — without
   this exception they took 1500px of document height and pushed the
   wordmark off the first viewport. */
.chrome-hero > *:not(.chrome-hero__metal-bg):not(.chrome-hero__scrim) {
  position: relative;
  z-index: 2;
}

.chrome-hero__eyebrow {
  margin: 0 0 1rem;
  font-family: var(--chrome-font-mono);
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--chrome-accent-deep);
}

.chrome-hero__titlewrap {
  position: relative;
  width: 100%;
  max-width: min(92vw, 1100px);
  padding: clamp(0.6rem, 1.5vw, 1.4rem) 0;
}

/*
 * The holographic foil frame around the wordmark. Three offset conic bands
 * (sky / pink / mint) in mix-blend-mode: screen over a silver base; their
 * angular origins shift with --chrome-px / --chrome-py (pointer parallax).
 * Decorative; the headline sits on top in AA-safe chrome-ink.
 */
.chrome-foil {
  position: absolute;
  inset: -8% -4%;
  pointer-events: none;
  z-index: 1;
  --shift-x: calc(var(--chrome-px) * 1deg);
  --shift-y: calc(var(--chrome-py) * 1deg);
}

.chrome-foil__band {
  position: absolute;
  inset: 0;
  mix-blend-mode: screen;
  opacity: 0.55;
  will-change: background;
}

.chrome-foil__band--sky {
  background: conic-gradient(
    from calc(0deg + var(--shift-x)),
    var(--chrome-glow-sky),
    var(--chrome-holo-mist),
    var(--chrome-glow-sky)
  );
  filter: blur(18px);
  opacity: 0.5;
}

.chrome-foil__band--pink {
  background: conic-gradient(
    from calc(120deg + calc(var(--shift-x) * -0.6)),
    var(--chrome-glow-pink),
    var(--chrome-holo-pink),
    var(--chrome-glow-pink)
  );
  filter: blur(26px);
  opacity: 0.45;
  transform: scale(1.04);
}

.chrome-foil__band--mint {
  background: conic-gradient(
    from calc(240deg + calc(var(--shift-x) * 0.4)),
    var(--chrome-glow-mint),
    var(--chrome-holo-mint),
    var(--chrome-glow-mint)
  );
  filter: blur(34px);
  opacity: 0.4;
  transform: scale(1.08);
}

/*
 * The wordmark. Three layered elements:
 *  1. .chrome-wordmark__fill — a CSS chrome-gradient TEXT fill, the honest
 *     fallback. Always visible; the canvas sits on top of it.
 *  2. .chrome-wordmark__metal — the WebGL canvas, clipped to the glyph
 *     shapes via mix-blend-mode: screen over the fill, transparent until
 *     its first real frame (.is-live).
 *  3. .chrome-wordmark__glyphs — the per-character sweep reveal, laid out
 *     as the visible (opaque ink) glyphs that clip open then sweep.
 *
 * The layout is driven by __glyphs; __fill and __metal are absolutely
 * positioned to match its metrics. Each glyph carries its index in
 * --chrome-ci for the sweep stagger.
 */
.chrome-wordmark {
  position: relative;
  display: inline-block;
  margin: 0;
  font-family: var(--chrome-font-display);
  font-weight: 800;
  font-size: clamp(2.6rem, 9vw, 6rem);
  line-height: 0.92;
  letter-spacing: -0.02em;
  color: var(--chrome-ink);
}

.chrome-wordmark__fill {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  /* Solid silver chrome — opaque so the wordmark reads on ANY background
     (including the metal-bg render), with a beveled metal edge built from
     stacked text-shadows. No background-clip (which failed over imagery). */
  color: #f4f7fa;
  -webkit-text-fill-color: #f4f7fa;
  -webkit-text-stroke: 4px #1a1a28;
  paint-order: stroke fill;
  text-shadow:
    0 2px 0 #ffffff,
    0 3px 0 #c8d0d8,
    0 4px 1px rgba(0, 0, 0, 0.4),
    0 5px 3px rgba(0, 0, 0, 0.4),
    0 7px 8px rgba(0, 0, 0, 0.45),
    0 10px 18px rgba(0, 0, 0, 0.35);
  z-index: 4;
}

.chrome-wordmark__metal {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  mix-blend-mode: screen;
  z-index: 3;
  pointer-events: auto;
}

/* The canvas only appears once its first real frame has been drawn. */
.chrome-js .chrome-wordmark__metal.is-live {
  opacity: 0.9;
  transition: opacity 900ms var(--chrome-ease-foil);
}

.chrome-wordmark__glyphs {
  position: relative;
  display: flex;
  justify-content: center;
  z-index: 4;
  pointer-events: none;
}

/*
 * The per-glyph sweep reveal. CSS default = fully visible (no-JS, reduced
 * motion rest here). Under .chrome-js, each glyph starts clipped to nothing
 * (inset(0 100% 0 0)) and a metallic sweep crosses it as it becomes
 * visible — the clip-path wipes left-to-right while a chrome ::after
 * highlight band passes across the glyph.
 */
.chrome-wordmark__ch {
  display: inline-block;
  position: relative;
  color: transparent;
  -webkit-text-fill-color: transparent;
}

/* The glyphs themselves are invisible ink — they exist only for layout +
   the clip mask. The visible metal is __fill + __metal beneath them. We
   make them transparent so the layered fill/metal show through, while
   their box still defines the headline's metrics. */
.chrome-js .chrome-wordmark__ch {
  clip-path: inset(0 100% 0 0);
  transition: clip-path 620ms var(--chrome-ease-chrome);
  transition-delay: calc(var(--chrome-ci, 0) * 55ms);
}

.chrome-js .chrome-wordmark.is-visible .chrome-wordmark__ch {
  clip-path: inset(0 0 0 0);
}

