/* ==========================================================================
   Holographic foil panel (shared by cards + manifesto plaque)
   ========================================================================== */

.chrome-holofoil {
  position: relative;
  display: flex;
  flex-direction: column;
  border-radius: 4px;
  background: var(--chrome-silver);
  overflow: hidden;
  isolation: isolate; /* contain mix-blend-mode: screen inside the panel */
  --shift-x: calc(var(--chrome-px) * 1deg);
  --shift-y: calc(var(--chrome-py) * 1deg);
}

.chrome-holofoil__base {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    125deg,
    var(--chrome-silver) 0%,
    var(--chrome-highlight) 35%,
    var(--chrome-silver) 55%,
    var(--chrome-ink-soft) 100%
  );
  z-index: 0;
}

.chrome-holofoil__band {
  position: absolute;
  inset: -10%;
  mix-blend-mode: screen;
  pointer-events: none;
}

.chrome-holofoil__band--sky {
  background: conic-gradient(
    from calc(0deg + var(--shift-x)),
    var(--chrome-glow-sky) 0%,
    transparent 30%,
    var(--chrome-holo-sky) 55%,
    transparent 80%,
    var(--chrome-glow-sky) 100%
  );
  filter: blur(10px);
  opacity: 0.6;
  z-index: 1;
}

.chrome-holofoil__band--pink {
  background: conic-gradient(
    from calc(120deg + calc(var(--shift-x) * -0.6)),
    var(--chrome-glow-pink) 0%,
    transparent 35%,
    var(--chrome-holo-pink) 60%,
    transparent 85%,
    var(--chrome-glow-pink) 100%
  );
  filter: blur(14px);
  opacity: 0.5;
  z-index: 2;
}

.chrome-holofoil__band--mint {
  background: conic-gradient(
    from calc(240deg + calc(var(--shift-x) * 0.4)),
    var(--chrome-glow-mint) 0%,
    transparent 35%,
    var(--chrome-holo-mint) 60%,
    transparent 85%,
    var(--chrome-glow-mint) 100%
  );
  filter: blur(18px);
  opacity: 0.45;
  z-index: 3;
}

/* a moving white specular streak across the panel — the "wet" read */
.chrome-holofoil__spec {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 38%,
    rgba(255, 255, 255, 0.55) 48%,
    rgba(255, 255, 255, 0.2) 52%,
    transparent 62%
  );
  background-size: 280% 280%;
  background-position: calc(50% + var(--chrome-px) * 40%) calc(50% + var(--chrome-py) * 40%);
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 4;
}

