/* ==========================================================================
   Chrome button — the wet metal pill
   ========================================================================== */

.chrome-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.95rem 2rem;
  min-height: 52px;
  font-family: var(--chrome-font-display);
  font-weight: 800;
  font-size: 0.92rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--chrome-highlight); /* 14.09:1 on the chrome-ink core */
  background: var(--chrome-ink);   /* the dark chrome core */
  border: none;
  border-radius: 999px;
  cursor: pointer;
  isolation: isolate;
  transition: transform 220ms var(--chrome-ease-foil);
  -webkit-tap-highlight-color: transparent;
}

/* the chrome-silver frame around the dark core */
