  position: absolute;
  inset: -3px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    var(--chrome-highlight) 0%,
    var(--chrome-silver) 45%,
    var(--chrome-ink-soft) 100%
  );
  z-index: -1;
}

/* the wet top sheen — a white band across the top half */
.chrome-btn__sheen {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.9) 0%,
    rgba(255, 255, 255, 0.35) 40%,
    transparent 55%
  );
  mix-blend-mode: screen;
}

/* the breathing holographic accent rim glow */
