  position: absolute;
  inset: -2px;
  border-radius: 999px;
  box-shadow: 0 0 0 1px var(--chrome-accent), 0 0 18px 2px var(--chrome-accent);
  opacity: 0.4;
  z-index: -2;
}

.chrome-js .chrome-btn__rim {
  animation: chrome-glow 4.2s var(--chrome-ease-foil) infinite;
}

.chrome-btn__label {
  position: relative;
  z-index: 1;
}

.chrome-btn:hover {
  transform: translateY(-2px);
}

.chrome-btn:hover .chrome-btn__rim {
  opacity: 0.8;
}

.chrome-btn:active {
  transform: translateY(0) scale(0.98);
}

.chrome-btn:focus-visible {
  outline: 2px solid var(--chrome-accent);
  outline-offset: 4px;
}

