  font-size: 0.95rem;
  line-height: 2;
  letter-spacing: 0.03em;
  color: var(--chrome-ink);
}

.chrome-footer__address :lang(ko) {
  color: var(--chrome-ink-2);
}

.chrome-footer__legal {
  margin: 0;
  font-family: var(--chrome-font-mono);
  font-size: 0.78rem;
  letter-spacing: 0.05em;
  color: var(--chrome-ink-soft);
}

/* ==========================================================================
   Reveals — all pre-states gated behind .chrome-js
   ========================================================================== */

.chrome-js [data-reveal="fade"] {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity var(--chrome-reveal-ms) var(--chrome-ease-foil),
    transform var(--chrome-reveal-ms) var(--chrome-ease-foil);
  will-change: opacity, transform;
}

.chrome-js [data-reveal="fade"].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Keyframes — transform / opacity only
   ========================================================================== */

@keyframes chrome-hint {
  0%,
  100% {
    opacity: 0.5;
    transform: translateY(0);
  }
  50% {
    opacity: 0.85;
    transform: translateY(5px);
  }
}

@keyframes chrome-glow {
  0%,
  100% {
    opacity: 0.35;
  }
  50% {
    opacity: 0.7;
  }
}

/* ==========================================================================
   Reduced motion — everything settles into one composed, static state:
   the headline rests in its CSS chrome-gradient fill (no shader loop), the
   foil sits in its neutral rainbow, glyphs are fully unclipped, reveals
   appear instantly, nothing pulses.
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .chrome-js .chrome-hero__hint,
  .chrome-js .chrome-btn__rim {
    animation: none;
  }

  .chrome-js .chrome-wordmark__ch {
    clip-path: none !important;
    transition: none;
  }

  .chrome-js .chrome-wordmark__metal.is-live {
    transition: none;
    opacity: 0.85;
  }

  .chrome-js [data-reveal="fade"] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .chrome-btn {
    transition: none;
  }
}
